/* Generated by Trae Work
   问道 WenDao · 项目全景梳理 —— 图表与结构图初始化
   Palette: Product Teal (accent #12B886 / #228BE6 / #7950F2 / #E64980)
   契约：renderer=svg、animation=false、tooltip.appendToBody=true、resize 监听 */
(function () {
  'use strict';

  /* ---- Product Teal 解析色（写死，Mermaid / ECharts 均不依赖 CSS 变量） ---- */
  var C = {
    teal: '#12B886',
    blue: '#228BE6',
    purple: '#7950F2',
    pink: '#E64980',
    ink: '#1B2422',
    axis: '#66756F',
    grid: 'rgba(27, 36, 34, 0.10)',
    line: '#94A29C',
    soft: '#E6F8F1',
    softText: '#0B6B4F',
    surface: '#EDF3F1',
    border: '#D5E0DC'
  };

  var FONT = '"Noto Sans CJK SC", "WenQuanYi Micro Hei", -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif';

  var instances = [];

  function mount(el) {
    if (!el || typeof echarts === 'undefined') return null;
    var inst = echarts.init(el, null, { renderer: 'svg' });
    instances.push(inst);
    return inst;
  }

  function tooltipBase() {
    return {
      appendToBody: true,
      backgroundColor: '#FFFFFF',
      borderColor: C.border,
      borderWidth: 1,
      padding: [8, 12],
      textStyle: { color: C.ink, fontFamily: FONT, fontSize: 13 },
      extraCssText: 'box-shadow: 0 4px 16px rgba(27,36,34,0.12); border-radius: 8px;'
    };
  }

  /* ============ 图 2：知识资产条目数（水平条形） ============ */
  function renderKnowledge() {
    var el = document.getElementById('chart-knowledge');
    var chart = mount(el);
    if (!chart) return;

    var rows = [
      { name: '本体术语（EXMO + RehabO）', value: 433 },
      { name: '动作条目', value: 201 },
      { name: '循证条目', value: 84 },
      { name: '数据集登记', value: 82 },
      { name: '代谢当量（MET）', value: 73 },
      { name: '家庭用药安全', value: 64 },
      { name: '补剂常识', value: 24 },
      { name: '疾病—运动映射', value: 8 }
    ];

    var names = rows.map(function (r) { return r.name; });
    var accent = [C.teal, C.teal, C.blue, C.blue, C.purple, C.purple, C.pink, C.pink];
    var data = rows.map(function (r, i) {
      return { value: r.value, itemStyle: { color: accent[i] } };
    });

    chart.setOption({
      animation: false,
      textStyle: { fontFamily: FONT },
      grid: { left: 8, right: 48, top: 12, bottom: 8, containLabel: true },
      tooltip: (function () {
        var t = tooltipBase();
        t.trigger = 'axis';
        t.axisPointer = { type: 'shadow', shadowStyle: { color: 'rgba(18,184,134,0.08)' } };
        return t;
      })(),
      xAxis: {
        type: 'value',
        axisLine: { show: false },
        axisTick: { show: false },
        axisLabel: { color: C.axis, fontFamily: FONT, fontSize: 12 },
        splitLine: { lineStyle: { color: C.grid } }
      },
      yAxis: {
        type: 'category',
        inverse: true,
        data: names,
        axisLine: { lineStyle: { color: C.border } },
        axisTick: { show: false },
        axisLabel: { color: C.axis, fontFamily: FONT, fontSize: 12 }
      },
      series: [{
        type: 'bar',
        data: data,
        barWidth: '56%',
        itemStyle: { borderRadius: [0, 4, 4, 0] },
        label: {
          show: true,
          position: 'right',
          color: C.ink,
          fontFamily: FONT,
          fontSize: 12,
          fontWeight: 600,
          formatter: '{c}'
        },
        emphasis: { focus: 'series' }
      }]
    });
  }

  /* ============ 图 3：代码规模分布（垂直柱） ============ */
  function renderCode() {
    var el = document.getElementById('chart-code');
    var chart = mount(el);
    if (!chart) return;

    var rows = [
      { name: 'lib/ 客户端', value: 34680 },
      { name: 'test/ 测试', value: 6340 },
      { name: 'server/ 云端', value: 2389 },
      { name: 'scripts/ 构建脚本', value: 575 }
    ];
    var colors = [C.teal, C.blue, C.purple, C.pink];

    chart.setOption({
      animation: false,
      textStyle: { fontFamily: FONT },
      grid: { left: 8, right: 16, top: 32, bottom: 8, containLabel: true },
      tooltip: (function () {
        var t = tooltipBase();
        t.trigger = 'axis';
        t.axisPointer = { type: 'shadow', shadowStyle: { color: 'rgba(18,184,134,0.08)' } };
        t.valueFormatter = function (v) { return Number(v).toLocaleString('en-US') + ' 行'; };
        return t;
      })(),
      xAxis: {
        type: 'category',
        data: rows.map(function (r) { return r.name; }),
        axisLine: { lineStyle: { color: C.border } },
        axisTick: { show: false },
        axisLabel: { color: C.axis, fontFamily: FONT, fontSize: 12, interval: 0 }
      },
      yAxis: {
        type: 'value',
        axisLine: { show: false },
        axisTick: { show: false },
        axisLabel: {
          color: C.axis,
          fontFamily: FONT,
          fontSize: 12,
          formatter: function (v) { return v >= 1000 ? (v / 1000) + 'k' : v; }
        },
        splitLine: { lineStyle: { color: C.grid } }
      },
      series: [{
        type: 'bar',
        barWidth: '44%',
        data: rows.map(function (r, i) {
          return { value: r.value, itemStyle: { color: colors[i], borderRadius: [4, 4, 0, 0] } };
        }),
        label: {
          show: true,
          position: 'top',
          color: C.ink,
          fontFamily: FONT,
          fontSize: 12,
          fontWeight: 600,
          formatter: function (p) { return Number(p.value).toLocaleString('en-US'); }
        },
        emphasis: { focus: 'series' }
      }]
    });
  }

  /* ============ 图 1：系统架构结构图（Mermaid） ============ */
  function renderMermaid() {
    if (typeof mermaid === 'undefined') return;

    mermaid.initialize({
      startOnLoad: false,
      securityLevel: 'loose',
      theme: 'base',
      fontFamily: FONT,
      themeVariables: {
        fontFamily: FONT,
        fontSize: '14px',
        primaryColor: C.soft,
        primaryTextColor: C.softText,
        primaryBorderColor: C.teal,
        secondaryColor: C.surface,
        tertiaryColor: C.surface,
        lineColor: C.line,
        textColor: C.ink,
        background: '#FFFFFF',
        nodeBorder: C.teal,
        clusterBkg: '#F6F9F8',
        clusterBorder: C.border,
        edgeLabelBackground: '#FFFFFF'
      },
      flowchart: { htmlLabels: true, curve: 'basis', useMaxWidth: true }
    });

    var nodes = document.querySelectorAll('pre.mermaid');
    if (!nodes.length) return;
    if (typeof mermaid.run === 'function') {
      mermaid.run({ nodes: nodes });
    } else if (typeof mermaid.init === 'function') {
      mermaid.init(undefined, nodes);
    }
  }

  /* ============ 统一 resize ============ */
  function bindResize() {
    var timer = null;
    window.addEventListener('resize', function () {
      if (timer) window.clearTimeout(timer);
      timer = window.setTimeout(function () {
        instances.forEach(function (c) {
          if (c && !c.isDisposed()) c.resize();
        });
      }, 120);
    });
  }

  function boot() {
    try { renderKnowledge(); } catch (e) { /* 单图失败不阻断其他图 */ }
    try { renderCode(); } catch (e) { /* noop */ }
    try { renderMermaid(); } catch (e) { /* noop */ }
    bindResize();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }
})();
